/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { diff, fn, mathieuc, mathieucprime, mathieus, mathieusprime, rational, symbols } from '../../../src';
import { sympyStr } from '../../sympy-str';

describe("doctests of sympy.functions.special.mathieu_functions", () => {
  it("mathieuc(a, q, z)", () => {
    const [a, q, z] = symbols('a q z');
    expect(sympyStr(mathieuc(a, q, z))).toBe('mathieuc(a, q, z)');
  });
  it("mathieuc(a, 0, z)", () => {
    const [a, z] = symbols('a z');
    expect(sympyStr(mathieuc(a, rational(0), z))).toBe('cos(sqrt(a)*z)');
  });
  it("diff(mathieuc(a, q, z), z)", () => {
    const [a, q, z] = symbols('a q z');
    expect(sympyStr(diff(fn('mathieuc', [a, q, z]), z))).toBe('mathieucprime(a, q, z)');
  });
  it("mathieucprime(a, q, z)", () => {
    const [a, q, z] = symbols('a q z');
    expect(sympyStr(mathieucprime(a, q, z))).toBe('mathieucprime(a, q, z)');
  });
  it("mathieucprime(a, 0, z)", () => {
    const [a, z] = symbols('a z');
    expect(sympyStr(mathieucprime(a, rational(0), z))).toBe('-sqrt(a)*sin(sqrt(a)*z)');
  });
  it("diff(mathieucprime(a, q, z), z)", () => {
    const [a, q, z] = symbols('a q z');
    expect(sympyStr(diff(fn('mathieucprime', [a, q, z]), z))).toBe('(-a + 2*q*cos(2*z))*mathieuc(a, q, z)');
  });
  it("mathieus(a, q, z)", () => {
    const [a, q, z] = symbols('a q z');
    expect(sympyStr(mathieus(a, q, z))).toBe('mathieus(a, q, z)');
  });
  it("mathieus(a, 0, z)", () => {
    const [a, z] = symbols('a z');
    expect(sympyStr(mathieus(a, rational(0), z))).toBe('sin(sqrt(a)*z)');
  });
  it("diff(mathieus(a, q, z), z)", () => {
    const [a, q, z] = symbols('a q z');
    expect(sympyStr(diff(fn('mathieus', [a, q, z]), z))).toBe('mathieusprime(a, q, z)');
  });
  it("mathieusprime(a, q, z)", () => {
    const [a, q, z] = symbols('a q z');
    expect(sympyStr(mathieusprime(a, q, z))).toBe('mathieusprime(a, q, z)');
  });
  it("mathieusprime(a, 0, z)", () => {
    const [a, z] = symbols('a z');
    expect(sympyStr(mathieusprime(a, rational(0), z))).toBe('sqrt(a)*cos(sqrt(a)*z)');
  });
  it("diff(mathieusprime(a, q, z), z)", () => {
    const [a, q, z] = symbols('a q z');
    expect(sympyStr(diff(fn('mathieusprime', [a, q, z]), z))).toBe('(-a + 2*q*cos(2*z))*mathieus(a, q, z)');
  });
});
